const rp = (n) => 'Rp ' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const from = { Email: 'toko@wander.test', Name: 'Shop' };
const { data } = $input.first().json.body;
const lines = data.items.map((i) => '- ' + i.name + ' x' + i.quantity + ' = ' + rp(i.price * i.quantity)).join('
');
const detail = lines + '
Ongkir: ' + rp(data.shippingCost) + '
Total: ' + rp(data.total);
return [
  { json: { From: from, To: [{ Email: data.customer.email, Name: data.customer.name }],
    Subject: 'Pembayaran diterima - ' + data.code,
    Text: 'Halo ' + data.customer.name + ',

Pembayaran untuk pesanan ' + data.code + ' sudah kami terima.

' + detail + '

Dikirim ke: ' + data.shippingAddress + '

Terima kasih!' } },
  { json: { From: from, To: [{ Email: 'admin@wander.test', Name: 'Admin' }],
    Subject: '[Order PAID] ' + data.code + ' - ' + rp(data.total),
    Text: 'Order ' + data.code + ' dari ' + data.customer.name + ' (' + data.customer.email + ') sudah lunas.

' + detail + '

Alamat: ' + data.shippingAddress } },
];
